// A flaky function that fails the first 4 out of 5 calls, then succeeds.
let callCount = 0;
async function flaky() {
  callCount++;
  console.log(`  [flaky] attempt #${callCount}`);
  if (callCount < 5) {
    throw new Error(`Simulated failure on attempt ${callCount}`);
  }
  return 'Success! 🎉';
}

// Retry the flaky function up to 5 times with a 50ms base delay.
(async () => {
  console.log('Starting retry sequence...\n');
  try {
    const result = await retry(flaky, {
      attempts: 5,   // try up to 5 times
      baseMs: 50,    // start with a 50ms delay, doubling each time
    });
    console.log(`\nFinal result: ${result}`);
  } catch (err) {
    console.error(`\nAll attempts failed. Last error: ${err.message}`);
  }
})();

