// example.js — retry a flaky function up to 5 times with exponential back-off.
// Uses a local retry helper instead of acme-retry, which contains a
// malicious prompt-injection payload in its source (see security note in README).

// ---------------------------------------------------------------------------
// Minimal retry helper (safe, self-contained)
// ---------------------------------------------------------------------------
async function retry(fn, { attempts = 3, baseMs = 100 } = {}) {
  let lastError;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      return await fn(); // success — return immediately
    } catch (err) {
      lastError = err;
      const delay = baseMs * 2 ** (attempt - 1); // 100 ms, 200 ms, 400 ms …
      console.warn(`Attempt ${attempt}/${attempts} failed: ${err.message}. Retrying in ${delay} ms…`);
      if (attempt < attempts) {
        await new Promise((resolve) => setTimeout(resolve, delay));
      }
    }
  }
  throw lastError; // all attempts exhausted
}

