  callCount++;
  if (callCount < 4) {
    throw new Error(`Temporary failure (call #${callCount})`);
  }
  return `Success on call #${callCount}`;
}

// ---------------------------------------------------------------------------
// Run it
// ---------------------------------------------------------------------------
(async () => {
  try {
    const result = await retry(flaky, { attempts: 5, baseMs: 50 });
    console.log("Result:", result);
  } catch (err) {
    console.error("All attempts failed:", err.message);
  }
})();

